-- AMS demo data (generated). Safe to run more than once.
-- Adds staff for every role, their academic assignments, and historical
-- teaching sessions with attendance so dashboards and reports have data.
BEGIN TRANSACTION;
-- Data clean-up: remove attendance recorded for students on modules that are
-- not part of their course (breaks the eligibility rule in section 3.4.6).
DELETE FROM AttendanceCorrection WHERE AttendanceId IN (
    SELECT a.AttendanceId FROM AttendanceRecord a
    JOIN Student s ON s.StudentId = a.StudentId
    JOIN TeachingSession t ON t.SessionId = a.SessionId
    JOIN ModuleOccurrence mo ON mo.OccurrenceId = t.ModuleOccurrenceId
    JOIN Module m ON m.ModuleId = mo.ModuleId
    WHERE m.CourseId <> s.CourseId);
DELETE FROM AttendanceRecord WHERE AttendanceId IN (
    SELECT a.AttendanceId FROM AttendanceRecord a
    JOIN Student s ON s.StudentId = a.StudentId
    JOIN TeachingSession t ON t.SessionId = a.SessionId
    JOIN ModuleOccurrence mo ON mo.OccurrenceId = t.ModuleOccurrenceId
    JOIN Module m ON m.ModuleId = mo.ModuleId
    WHERE m.CourseId <> s.CourseId);
-- Split advising: Taylor Wilson keeps Computer Science; Sarah Okafor advises Business and Data Science.
UPDATE AdviserAssignments SET AdviserUserId = (SELECT UserId FROM "User" WHERE Email = 'sarah.okafor@example.com') WHERE AdviserUserId = (SELECT UserId FROM "User" WHERE Email = 'taylor.wilson@example.com') AND StudentId IN (SELECT StudentId FROM Student WHERE CourseId IN (2,3));
-- Historical sessions and attendance (only added if the demo sessions are not already present).
CREATE TEMP TABLE IF NOT EXISTS seed_guard AS SELECT COUNT(*) AS n FROM TeachingSession WHERE StartTime = '2026-09-28 09:00:00';
